import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { ExpiryDto, ExpiryService } from '../../services/expiry-service';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-qc-standard-expiry',
  imports: [CommonModule, RouterLink, FormsModule],
  templateUrl: './qc-standard-expiry.html',
  styleUrl: './qc-standard-expiry.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class QcStandardExpiry {
expiry: ExpiryDto[] = [];
  searchTerm = '';

  constructor(private service: ExpiryService, private cd: ChangeDetectorRef) {}

  ngOnInit() {
    
    this.service.getAllProducts().subscribe({
      next: (data) => {
        this.expiry = data;
         this.cd.markForCheck();
        console.log("Products from backend:", this.expiry);
      },
      error: (err) => console.error("Error fetching parties:", err)
    });
  }

  isExpired(expiryDate: string | Date): boolean {
  if (!expiryDate) return false;
  const today = new Date();
  const exp = new Date(expiryDate);
  // strip time to compare only dates
  today.setHours(0, 0, 0, 0);
  exp.setHours(0, 0, 0, 0);
  return today >= exp;
}


  filteredExpiries() {
    const term = this.searchTerm.toLowerCase();
    return this.expiry.filter(r =>
      r.productName.toLowerCase().includes(term) ||
      r.preservationDate.toLowerCase().includes(term) ||
      r.expiryDate.toLowerCase().includes(term) ||
      r.validity.toPrecision().includes(term) ||
      r.strength.toPrecision().includes(term) ||
      r.de.toPrecision().includes(term) ||
      r.da.toPrecision().includes(term) ||
      r.db.toPrecision().includes(term) ||
      r.dc.toPrecision().includes(term) 
    );
  }
}

